import {campaigns,autismSource} from '../../data/editorial';import {artworks,openProduct} from '../../data/catalog';import {openStore,openMine} from '../../stores/commerce';import LineIcon from '../../components/LineIcon.vue';
const current=ref(0),joinOpen=ref(false),interest=ref('品牌合作');let initialSection='';
onLoad(q=>{initialSection=q?.section||''});onReady(()=>{if(initialSection)uni.pageScrollTo({selector:'#'+initialSection,duration:0})});
function scroll(){uni.pageScrollTo({selector:'#origin',duration:400})}
function source(){
// #ifdef H5
window.open(autismSource.url,'_blank','noopener');
